content.output:
                    });
                }
                // Some servers send the partial answer in `delta.content`,
                // others in `delta.text`; older ones in `message.content`.
                // Use the first non-empty field so the text is not doubled
                // (a server that fills two of them sends the same text in each)
                const textFields = ["content", "text", "output_text"];
                const deltaFields = choice.delta;
                let foundTextField = null;
                for (const field of textFields) {
                    const value = deltaFields[field];
                    if (typeof value === "string" && value.length > 0) {
                        foundTextField = field;
                        break;
                    }
                }
                if (foundTextField) {
                    const delta = deltaFields[foundTextField];
                    if (typeof delta === "string" && delta.length > 0) {
                        appendText(block, delta);
                    }
                }
                if (choice?.delta?.tool_calls) {
                    for (const toolCall of choice.delta.tool_calls) {
                        const block = ensureToolCallBlock(toolCall);
                    }
                }
                if (choice?.finish_reason) {
                    finishBlock(block, choice.finish_reason);
                }
            }
        }
    }
    return blocks;
}
